import {
  OPEN_DIALOG_ADD,
  OPEN_DIALOG_EDIT,
  SET_INPUT_DIALOG_ADD,
  SET_INPUT_DIALOG_EDIT,
  SET_TITLE_ADD,
  SET_TITLE_EDIT,
  SUBMIT_CHART,
  // EDIT_TITLE,
  DEL_COLLUMN,
} from "./Constance";

export const initState = {
  handleDialogAdd: false,
  handleDialogEdit: false,
  indexOfCollumn: 0,
  inputCollumnAdd: "",
  inputCollumnEdit: "",
  titleCollumn: ["Tiêu đề 1", "Tiêu đề 2"],
  series: [
    {
      name: "Demo đoạn thẳng 1",
      type: "line",
      data: [0, 2],
    },
  ],
  options: {
    xaxis: {
      categories: ["Tiêu đề 1", "Tiêu đề 2"],
    },
    plotOptions: {
      bar: {
        horizontal: false,
        dataLabels: {
          position: "top",
        },
      },
    },
  },
};

const reducer = (state, action) => {
  switch (action.type) {
    case OPEN_DIALOG_ADD:
      return {
        ...state,
        handleDialogAdd: action.payload,
      };
    case OPEN_DIALOG_EDIT:
      return {
        ...state,
        handleDialogEdit: action.payload.val,
        inputCollumnEdit: state.titleCollumn[action.payload.index],
        indexOfCollumn: action.payload.index,
      };
    case SET_INPUT_DIALOG_ADD:
      return {
        ...state,
        inputCollumnAdd: action.payload,
      };
    case SET_INPUT_DIALOG_EDIT:
      return {
        ...state,
        inputCollumnEdit: action.payload,
      };
    case SET_TITLE_ADD:
      return {
        ...state,
        titleCollumn: [...state.titleCollumn, action.payload],
        series: [
          {
            name: "Demo1",
            type: "line",
            data: [...state.series[0].data],
          },
        ],
        options: {
          xaxis: {
            categories: [...state.titleCollumn, action.payload],
          },
        },
      };
    case SET_TITLE_EDIT:
      console.log(action.payload);

      const listTitle = state.titleCollumn; // mang ban truoc khi sua;
      listTitle.splice(action.payload.index, 1, action.payload.value);
      return {
        ...state,
        titleCollumn: listTitle,
        series: [
          {
            name: "Demo1",
            type: "line",
            data: [...state.series[0].data],
          },
        ],
        options: {
          xaxis: {
            categories: listTitle,
          },
        },
      };
    case DEL_COLLUMN:
      const titleData = [...state.titleCollumn];
      const valueData = [...state.series[0].data];
      return {
        ...state,
        titleCollumn: titleData,
        series: [
          {
            data: valueData,
          },
        ],
        options: {
          xaxis: {
            categories: titleData,
          },
        },
      };
    case SUBMIT_CHART:
      const arr = action.payload.map((item) => {
        return Number(item.value);
      });
      return {
        ...state,
        series: [
          {
            name: "Demo1",
            type: "line",
            data: arr,
          },
        ],
      };
    default:
      throw new Error("Invalid Action");
  }
};

export default reducer;
